#pragma once

#include <stddef.h>

typedef enum
{
    SAGE_TONE_IDLE = 0,
    SAGE_TONE_OMINOUS,
    SAGE_TONE_SARCASTIC,
    SAGE_TONE_DRY,
} sage_tone_t;

typedef struct
{
    const char *stem;
    sage_tone_t tone;
} sage_tone_entry_t;

// Generated by tools/gen_voicelines_tones.ps1 into the build dir.
extern const sage_tone_entry_t sage_tone_table[];
extern const size_t sage_tone_table_count;

// Resolve a voiceline path like "0:/voicelines/much_later.wav" to a tone.
// Unknown stems default to SAGE_TONE_OMINOUS and emit one printf line so
// missing entries are easy to spot in the serial log.
sage_tone_t sage_tone_from_path(const char *path);
